:root {

--bg: #faf8f4; --text: #1a1a1a; --accent: #8B7432;

--border: #d4c9a8; --light-bg: #f5f0e6; --verse: #2c1810;

* { margin:0; padding:0; box-sizing:border-box; }

body { font-family:'EB Garamond','Cormorant Garamond',Georgia,serif; background:var(--bg); color:var(--text); line-height:1.85; font-size:18px; }

.container { max-width:780px; margin:0 auto; padding:40px 30px 80px; }

.subtitle { font-size:1.15em; color:#5a5040; letter-spacing:1px; font-style:italic; }

.halacha-header { margin:55px 0 30px; padding:18px 25px; background:var(--light-bg); border-left:4px solid var(--accent); border-radius:0 4px 4px 0; }

.halacha-header h2 { font-family:'Cormorant Garamond',serif; font-size:1.5em; font-weight:600; color:var(--accent); }

.sa-excerpt { margin:0 0 30px; padding:15px 25px; background:linear-gradient(135deg,#f9f5ed,#f5f0e6); border:1px solid var(--border); border-radius:4px; font-style:italic; color:#3a3020; font-size:0.97em; }

.sa-label { display:block; font-size:0.8em; text-transform:uppercase; letter-spacing:1.5px; color:var(--accent); font-style:normal; margin-bottom:6px; font-weight:600; }

.sub-header { margin:35px 0 15px; padding:10px 20px; background:#f0ebe0; border-left:3px solid var(--border); font-family:'Cormorant Garamond',serif; font-size:1.15em; font-weight:600; color:#5a5040; }

.verse { color:var(--verse); font-style:italic; }

.source { font-size:0.88em; color:#6b5e4c; }

.aramaic { font-style:italic; color:#4a3f2f; }

.key { font-weight:600; color:var(--accent); }

Likutay Halachos

Orach Chaim – Volume 1
